import { useState } from "react"
import { ContainerDiv, Dropdown } from "./style"
import { useNavigate } from "react-router-dom";

const MenuHamburger = () => {
    const [active, setActive] = useState(false);

    const navigate = useNavigate();
    const rotaHome = () => {
        navigate('/')
    }
    const routeForm = () => {
        navigate('/formNutri')
    }
    function menuShow() {
        let menuMobile = document.querySelector('.mobile-menu');
        if (!menuMobile){

        }else{
            if (menuMobile.classList.contains('open')) {
                menuMobile.classList.remove('open');
            } else {
                menuMobile.classList.add('open');
            }
        }
        }

        return (
            <>
                <ContainerDiv>
                    <nav className="nav-bar">
                        <div onClick={() => {setActive(!active)}} className="mobile-menu-icon">
                            <button onClick={() => (menuShow())}> <i className={active ? 'bx bx-x' : 'bx bx-menu'}></i> </button>
                        </div>
                    </nav>
                    <div className="mobile-menu">
                        <ul>
                            <a className="nav-item" onClick={rotaHome}>Home</a>
                            <a className="nav-item" href="#sobre">Sobre</a>
                            <div className="hover">
                                <a className="nav-item" >Cidades</a>
                                <Dropdown className="dropdown-content">
                                    <ul>
                                        <li><a onClick={rotaHome}>Home</a></li>
                                        <li><a onClick={routeForm}>Formulário</a></li>
                                        <li><a>Contato</a></li>
                                    </ul>
                                </Dropdown>
                            </div>
                                <a className="nav-item">Contato</a>
                        </ul>
                    </div>
                </ContainerDiv>
            </>
        )
}

export default MenuHamburger
